/**
 * @file src/tableau/dynamic-modification.ts
 * @description Runtime tableau modification operations
 *
 * Supports modifying the LP after initial solve:
 * - Add/remove constraints
 * - Add/remove variables
 * - Update constraint coefficients and RHS values
 * - Update objective function costs
 *
 * Functions are designed to be bound to a Tableau instance via `this`.
 */
import type Tableau from "./tableau";
import type { Constraint, Variable } from "../expressions";
export declare function putInBase(this: Tableau, varIndex: number): number;
export declare function takeOutOfBase(this: Tableau, varIndex: number): number;
export declare function updateVariableValues(this: Tableau): void;
export declare function updateRightHandSide(this: Tableau, constraint: Constraint, difference: number): void;
export declare function updateConstraintCoefficient(this: Tableau, constraint: Constraint, variable: Variable, difference: number): void;
export declare function updateCost(this: Tableau, variable: Variable, difference: number): void;
export declare function addConstraint(this: Tableau, constraint: Constraint): void;
export declare function removeConstraint(this: Tableau, constraint: Constraint): void;
export declare function addVariable(this: Tableau, variable: Variable): void;
export declare function removeVariable(this: Tableau, variable: Variable): void;
